{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/lab",
  "data": {
    "name": "CommentThread",
    "displayName": "Comment Thread",
    "group": "Comments",
    "category": "Chat",
    "keywords": [
      "comment",
      "comment thread",
      "thread",
      "replies",
      "margin comment",
      "annotation"
    ],
    "description": "One comment thread on its own: its first comment, one level of replies, reactions, edit history, controlled typing and seen metadata, and a reply composer. For a margin comment beside a document, a popover under a highlight, or any surface that shows a single thread.",
    "usage": {
      "description": "A comment thread shows one conversation: its first comment and the replies under it. Use it where a surface shows a single thread, such as a margin card beside a document or a popover opened from a highlight. To show many threads with a composer for new ones, use Comments.",
      "anatomy": [
        {
          "name": "Surface",
          "required": true,
          "description": "An outlined Card on a page, or a Section without outer rules inside a card or popover. A press anywhere on it opens the thread; a visually hidden toggle carries its name and focus."
        },
        {
          "name": "Quoted passage",
          "required": false,
          "description": "The passage an inline comment discusses, as an italic blockquote ruled in the highlight color, with an Outdated badge once the passage is edited away."
        },
        {
          "name": "First comment",
          "required": true,
          "description": "Avatar, header (name, time, Edited, Resolved, and the actions shown on hover or focus), Markdown body clamped to three lines until the thread opens, and reactions."
        },
        {
          "name": "Replies",
          "required": false,
          "description": "One level of replies behind View replies, joined to the first comment by an avatar rail while the thread is open. A host-marked unread reply reveals without selecting the thread, moving focus, or opening the reply composer."
        },
        {
          "name": "Live state",
          "required": false,
          "description": "Controlled typing state follows the conversation while the thread is open, with its pulsing dots in the avatar column and its label on the comment-text line. Controlled `seenBy` metadata remains available to comment render callbacks but has no default presentation."
        },
        {
          "name": "Reply composer",
          "required": false,
          "description": "A CommentComposer that opens with the thread, beside the viewer’s avatar."
        }
      ],
      "bestPractices": [
        {
          "guidance": true,
          "description": "Inside a card or popover, set `container=\"card\"` and give the card no padding: the thread supplies its own insets and draws no outer rules."
        },
        {
          "guidance": true,
          "description": "Control `isSelected` when the thread opens from elsewhere, such as its highlight in a document. Controlled selection reveals the body and replies without moving focus or opening the reply composer."
        },
        {
          "guidance": true,
          "description": "In a Popover over a document, pass `onDismiss` and pair it with `hasLightDismiss={false}` and `hasEscapeDismiss={false}` on the host Popover. A press outside the thread or Escape then closes it, except that the first one over an unsaved reply or edit shakes the thread and keeps the draft."
        },
        {
          "guidance": true,
          "description": "Map your collaboration state to `typingUsers` and `seenBy`, then publish local reply and edit activity with `onComposerDraftChange`. `seenBy` stays hidden unless a comment render callback presents it. The thread never opens a connection or expires participants."
        },
        {
          "guidance": false,
          "description": "Stack several CommentThreads with a composer to build a discussion. Use Comments, which keeps one thread open at a time and orders threads with activity."
        },
        {
          "guidance": false,
          "description": "Wrap the thread in your own button or link to open it. The thread is already one toggle; a second control nests interactive elements."
        },
        {
          "guidance": false,
          "description": "Leave the host Popover’s light dismiss on while passing `onDismiss`. The browser closes the Popover before the thread can keep a draft."
        }
      ],
      "accessibility": [
        {
          "name": "Escape",
          "category": "Keyboard",
          "criterion": "2.1.1 Keyboard",
          "description": "With `onDismiss`, Escape dismisses the thread only when no layer inside it is open. An open emoji picker, menu, or dialog closes first, one Escape at a time."
        },
        {
          "name": "Unsaved draft warning",
          "category": "Semantics",
          "criterion": "4.1.3 Status Messages",
          "description": "When a dismissal would discard an unsaved reply or edit, the thread stays open, focus returns to the draft, and a polite live region says the draft is unsaved and that dismissing again discards it. The shake is never the only signal."
        },
        {
          "name": "Reduced motion",
          "criterion": "2.3.3 Animation from Interactions",
          "description": "Under `prefers-reduced-motion: reduce` the thread does not shake. Focus and the announcement still mark the kept draft."
        }
      ]
    },
    "props": [
      {
        "name": "comment",
        "type": "CommentThreadData",
        "required": true,
        "description": "The thread: its first comment, carrying its replies, reactions, optional anchor, transient `typingUsers`, and per-comment `seenBy` metadata. `seenBy` is not rendered by default but remains available to comment render callbacks."
      },
      {
        "name": "isSelected",
        "type": "boolean",
        "description": "Whether the thread is open, controlled: body unclamped and replies shown. Omit it to let the thread own selection. Host-controlled selection never moves focus or opens the reply composer; a viewer Reply action does."
      },
      {
        "name": "onSelectedChange",
        "type": "(isSelected: boolean) => void",
        "description": "Called when the viewer opens or closes the thread."
      },
      {
        "name": "onDismiss",
        "type": "() => void",
        "description": "Hands the thread its anchored host’s light dismissal. A press outside the thread, or an Escape no layer inside it handled, calls it. While a reply or edit holds unsaved text, the first request instead shakes the thread, returns focus to the draft, and announces; the next consecutive request dismisses, and typing or pressing inside the thread re-arms the warning. Pair it with `hasLightDismiss={false}` and `hasEscapeDismiss={false}` on the host Popover. Omit it and the thread never dismisses anything."
      },
      {
        "name": "currentUser",
        "type": "CommentUser",
        "description": "The viewer, for own-comment actions and the reply avatar."
      },
      {
        "name": "mode",
        "type": "'interactive' | 'non-editable' | 'read-only'",
        "default": "'interactive'",
        "description": "Which actions show, as on Comments."
      },
      {
        "name": "container",
        "type": "'section' | 'card'",
        "default": "'section'",
        "description": "The parent surface: an outlined Card on a page, or a Section without outer rules inside a card or popover."
      },
      {
        "name": "onSubmit",
        "type": "(content: string, parentCommentId?: string) => void | Promise<void>",
        "description": "Posts a reply, always with the thread’s first comment as the parent. A rejected Promise restores the draft and shows an error with Retry."
      },
      {
        "name": "onComposerDraftChange",
        "type": "(value: string, context: CommentComposerContext) => void",
        "description": "Reports internally owned reply and edit drafts, including seeds and an empty value after submit, cancel, or a target switch. Route updates by `context` and own transport timing in your app."
      },
      {
        "name": "onSaveEdit",
        "type": "(commentId: string, content: string) => void | Promise<void>",
        "description": "Adds Edit to the viewer’s own comments and saves the new Markdown."
      },
      {
        "name": "onDelete",
        "type": "(commentId: string) => void | Promise<void>",
        "description": "Adds Delete to the viewer’s own comments, confirmed in a dialog first."
      },
      {
        "name": "onReact",
        "type": "(commentId: string, reactionKey: string, option?: CommentReactionOption) => void | Promise<void>",
        "description": "Toggles the viewer’s reaction by its stable key."
      },
      {
        "name": "onRetryComment",
        "type": "(commentId: string) => void | Promise<void>",
        "description": "Adds Retry to a comment whose `status` is `error`."
      },
      {
        "name": "onResolveThread",
        "type": "(commentId: string) => void | Promise<void>",
        "description": "Adds Mark as resolved to an open thread."
      },
      {
        "name": "onReopenThread",
        "type": "(commentId: string) => void | Promise<void>",
        "description": "Adds Reopen to a resolved thread."
      },
      {
        "name": "loadVersions",
        "type": "(commentId: string) => Promise<readonly CommentVersion[]>",
        "description": "Loads a comment’s edit history, newest first."
      },
      {
        "name": "onUploadImages",
        "type": "(files: readonly File[], context: CommentComposerContext) => CommentUploadedImage[] | Promise<CommentUploadedImage[]>",
        "description": "Uploads images attached, pasted, or dropped in the reply composer and appends them as Markdown images."
      },
      {
        "name": "isSubmitting",
        "type": "boolean",
        "default": "false",
        "description": "Host-controlled pending state for the reply composer."
      },
      {
        "name": "composerPlaceholder",
        "type": "string",
        "description": "Placeholder of the reply composer. Defaults to the localized \"Reply to <name>…\"."
      },
      {
        "name": "highlightColor",
        "type": "'blue' | 'cyan' | 'gray' | 'green' | 'orange' | 'pink' | 'purple' | 'red' | 'teal' | 'yellow'",
        "default": "'yellow'",
        "description": "The palette color your app highlights the thread’s passage in."
      },
      {
        "name": "reactionOptions",
        "type": "readonly CommentReactionOption[]",
        "default": "DEFAULT_COMMENT_REACTIONS",
        "description": "The reactions Add reaction offers."
      },
      {
        "name": "agentCommands",
        "type": "readonly CommentAgentCommand[]",
        "description": "Agents a reply can address with a `/` command."
      },
      {
        "name": "composerTriggers",
        "type": "readonly ChatComposerTrigger[]",
        "description": "Typeahead triggers for the reply composer, such as an `@` people search."
      },
      {
        "name": "markdownPlugins",
        "type": "readonly MarkdownPluginEntry[]",
        "description": "Block Markdown plugins for comment bodies."
      },
      {
        "name": "markdownInlinePlugins",
        "type": "readonly MarkdownInlinePlugin[]",
        "description": "Inline Markdown plugins for comment bodies, such as mentions."
      },
      {
        "name": "getReplyMention",
        "type": "(author: CommentUser) => string | undefined",
        "description": "Seeds a reply to a reply with a mention of its author."
      },
      {
        "name": "hasEmojiPicker",
        "type": "boolean",
        "default": "true",
        "description": "Whether the reply composer offers the emoji picker."
      },
      {
        "name": "renderAnchor",
        "type": "(comment: CommentThreadData, defaultAnchor: ReactNode) => ReactNode",
        "description": "Replaces the thread’s quoted passage."
      },
      {
        "name": "renderBody",
        "type": "(comment: CommentData) => ReactNode",
        "description": "Replaces a comment’s Markdown body."
      },
      {
        "name": "renderVersionBody",
        "type": "(version: CommentVersion) => ReactNode",
        "description": "Replaces the body of a version in the edit history."
      },
      {
        "name": "renderAdditionalActions",
        "type": "(comment: CommentData) => ReactNode",
        "description": "Adds product actions to a comment’s header."
      },
      {
        "name": "renderComposer",
        "type": "(props: CommentComposerRenderProps) => ReactNode",
        "description": "Replaces the reply composer’s input while the thread keeps its draft and state."
      }
    ],
    "examples": [
      {
        "label": "Margin comment",
        "code": "import {Card} from '@astryxdesign/core/Card';\nimport {CommentThread} from '@astryxdesign/lab';\n\n<Card padding={0} width={320}>\n  <CommentThread\n    comment={{\n      id: 'margin',\n      author: {id: 'maya', name: 'Maya Chen'},\n      body: 'Should this say three days? The dry run adds one.',\n      createdAt: '2026-09-30T19:00:00Z',\n      anchor: {quote: 'The final cohort completes rollout in two days.'},\n    }}\n    currentUser={{id: 'avery', name: 'Avery Kim'}}\n    container=\"card\"\n    onSubmit={(body, parentId) => postReply(parentId, body)}\n  />\n</Card>"
      },
      {
        "label": "In a popover that keeps unsaved drafts",
        "code": "import {useState} from 'react';\nimport {Button} from '@astryxdesign/core/Button';\nimport {Popover} from '@astryxdesign/core/Popover';\nimport {CommentThread} from '@astryxdesign/lab';\n\nfunction CommentPopover({thread, viewer}) {\n  const [isOpen, setIsOpen] = useState(false);\n  return (\n    <Popover\n      isOpen={isOpen}\n      onOpenChange={setIsOpen}\n      hasLightDismiss={false}\n      hasEscapeDismiss={false}\n      label=\"Comment\"\n      padding={0}\n      width={340}\n      content={\n        <CommentThread\n          comment={thread}\n          currentUser={viewer}\n          container=\"card\"\n          isSelected\n          onSubmit={(body, parentId) => postReply(parentId, body)}\n          onDismiss={() => setIsOpen(false)}\n        />\n      }>\n      <Button label=\"1 comment\" variant=\"secondary\" />\n    </Popover>\n  );\n}"
      }
    ],
    "package": "@astryxdesign/lab",
    "import": "@astryxdesign/lab",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
